const titre = document.querySelector("#app").dataset.titre;
function App() {
  const [choisi, setChoisi] = useState(false);
  return <main><h1 id="titre">{titre}</h1><p id="statut">{choisi ? "Choisi" : "Non choisi"}</p><button id="basculer" type="button" aria-pressed={choisi} onClick={() => setChoisi(!choisi)}>Basculer le choix</button><button id="annuler" type="button" onClick={() => setChoisi(false)}>Annuler</button></main>;
}
root.render(<App />);

